"""Date filter parsing for TTDL's date selectors."""
from datetime import date, timedelta
import calendar
import re

WEEKDAYS = {n[:3].lower(): i for i, n in enumerate(calendar.day_name)}

def shift_month(d, n):
    m=d.month-1+n
    y=d.year+m//12; m=m%12+1
    return date(y,m,min(d.day,calendar.monthrange(y,m)[1]))

def date_value(s, today=None):
    today=today or date.today()
    if not s: return None
    s=s.lower()
    if s=='today': return today
    if s=='tomorrow': return today+timedelta(days=1)
    if s=='yesterday': return today-timedelta(days=1)
    if s in ('first','-first'):
        first=date(today.year,today.month,1)
        if s=='first': return shift_month(first,1)
        return shift_month(first,-1) if today.day==1 else first
    if s=='last' or s=='-last':
        first=date(today.year,today.month,1)
        if s=='-last': first=shift_month(first,-1)
        else:
            nxt=shift_month(first,1)
            if today.day==calendar.monthrange(today.year,today.month)[1]: nxt=shift_month(nxt,1)
            return nxt-timedelta(days=1)
        return first-timedelta(days=1)
    neg=s.startswith('-'); w=s[1:] if neg else s
    if w in WEEKDAYS:
        delta=(WEEKDAYS[w]-today.weekday())%7
        if delta==0: delta=7
        if neg: delta-=7
        return today+timedelta(days=delta)
    if re.fullmatch(r'-?\d+[dwmy](?:\d+[dwmy])*',s):
        sign=-1 if neg else 1
        total=0
        for n,u in re.findall(r'(\d+)([dwmy])',w):
            n=int(n)*sign
            if u=='d': total+=n
            elif u=='w': total+=7*n
            elif u=='m': return shift_month(today,n) + timedelta(days=total)
            else: return shift_month(today,12*n) + timedelta(days=total)
        return today+timedelta(days=total)
    try: return date.fromisoformat(s)
    except ValueError: return None

def matches_date(value, spec, today=None):
    """value is ISO date text/None; returns whether it satisfies spec."""
    today=today or date.today(); spec=(spec or '').lower()
    if spec in ('any',''): return bool(value) if spec=='any' else True
    if spec=='none': return not value
    try: actual=date.fromisoformat(value) if value else None
    except ValueError: actual=None
    if spec=='soon': return actual is not None and actual <= today+timedelta(days=7)
    if spec=='overdue': return actual is not None and actual<today
    sep='..' if '..' in spec else ':' if ':' in spec else None
    if not sep:
        target=date_value(spec,today)
        return actual==target if target else False
    lo,hi=spec.split(sep,1)
    if lo=='none' or hi=='none':
        if actual is None: return True
        if lo=='none': lo=''
        if hi=='none': hi=''
    a=date_value(lo,today) if lo else None; b=date_value(hi,today) if hi else None
    if a and b and a>b: a,b=b,a
    return actual is not None and (a is None or actual>=a) and (b is None or actual<=b)

"""Matcher for TTDL's --filter expression language.

The matcher accepts mappings or objects. Standard record attributes are
recognized by their common names; unknown fields are read from a tags mapping.
"""
import re
from datetime import date, timedelta

ALIASES = {
    'id': 'id', 'priority': 'priority', 'pri': 'priority', 'done': 'done',
    'subject': 'subject', 'subj': 'subject', 'project': 'project', 'prj': 'project', '+': 'project',
    'context': 'context', 'ctx': 'context', '@': 'context', 'hashtag': 'hashtag', '#': 'hashtag',
    'completed': 'completed', 'created': 'created', 'create': 'created',
    'due': 'due', 'threshold': 'threshold', 'thr': 'threshold', 'rec': 'rec', 'time': 'time',
}

def _get(todo, name):
    if isinstance(todo, dict):
        if name in todo: return todo[name]
        tags = todo.get('tags', {})
    else:
        if hasattr(todo, name): return getattr(todo, name)
        tags = getattr(todo, 'tags', {})
    if isinstance(tags, dict): return tags.get(name)
    return None

def _values(v):
    if v is None: return []
    if isinstance(v, (list, tuple, set)): return list(v)
    if isinstance(v, bool): return [str(v).lower()]
    return [str(v)]

def _dateval(s):
    t = s.lower()
    today = date.today()
    if t == 'today': return today
    if t == 'tomorrow': return today + timedelta(days=1)
    if t == 'yesterday': return today - timedelta(days=1)
    m = re.fullmatch(r'([+-]?\d+)([dwmy]?)', t)
    if m:
        n, unit = int(m.group(1)), m.group(2)
        return today + timedelta(days=n * {'d':1,'w':7,'m':30,'y':365,'':1}[unit])
    try: return date.fromisoformat(s)
    except Exception: return None

def _match_value(val, wanted, field, regex):
    if wanted.lower() in ('any',): return bool(val)
    if wanted.lower() in ('none', '-'): return not bool(val)
    vals = _values(val)
    if not vals: return False
    if field == 'subject':
        needle = wanted.strip('*')
        try: return any(re.search(wanted, x, re.I) is not None if regex else needle.casefold() in x.casefold() for x in vals)
        except re.error: return False
    if '*' in wanted:
        pat = '^' + re.escape(wanted).replace(r'\*', '.*') + '$'
        try: return any(re.search(wanted, x, re.I) is not None if regex else re.match(pat,x,re.I) is not None for x in vals)
        except re.error: return False
    if regex:
        try: return any(re.search(wanted, x, re.I) is not None for x in vals)
        except re.error: return False
    lohi = wanted.split('..')
    if len(lohi) == 2:
        a, b = lohi
        # Date and numeric/priority ranges are inclusive.
        matched = False
        for x in vals:
            xv, av, bv = x, a, b
            if field in ('due','threshold','created','completed'):
                xv = _dateval(x); av = _dateval(a) if a else None; bv = _dateval(b) if b else None
            if field == 'id' or field == 'priority':
                xv = x.upper(); av = a.upper() if a else None; bv = b.upper() if b else None
            if xv is None: continue
            try:
                if (av is None or xv >= av) and (bv is None or xv <= bv): matched = True
            except TypeError: pass
        return matched
    return any(x.casefold() == wanted.casefold() for x in vals)

def matches_filter(todo, expression, regex=False):
    """Return whether todo matches a --filter expression (empty matches all)."""
    if not expression: return True
    sep = '~' if '~' in expression or regex else '|'
    for rule in expression.split(sep):
        passed = True
        for condition in rule.split(';'):
            cond = condition.strip()
            if not cond:
                continue
            negative = cond.startswith(('-', '!'))
            if negative: cond = cond[1:]
            if '=' in cond: key, raw = cond.split('=', 1)
            else: key, raw = cond, 'any'
            key = key.strip().lower()
            field = ALIASES.get(key, key)
            # done is a presence marker, not an ordinary valued field.
            if field == 'done':
                value = bool(_get(todo, 'done') or _get(todo, 'completed'))
                ok = value if raw.lower() in ('any', 'true', '1') else not value if raw.lower() in ('none','-','false','0') else value
            else:
                value = _get(todo, field)
                parts = raw.split(',')
                ok = any(_match_value(value, p.strip(), field, regex) for p in parts)
                if any(p.strip().startswith('-') and p.strip() not in ('-','none') for p in parts):
                    # A negative value excludes it while requiring a set field.
                    positives = [p.strip() for p in parts if not p.strip().startswith('-')]
                    negatives = [p.strip()[1:] for p in parts if p.strip().startswith('-')]
                    ok = bool(_values(value)) and (not positives or any(_match_value(value,p,field,regex) for p in positives)) and not any(_match_value(value,p,field,regex) for p in negatives)
            if negative: ok = not ok
            if not ok:
                passed = False; break
        if passed: return True
    return False
