        i=args.index('--todo-file'); path=Path(args[i+1]); del args[i:i+2]
    if '--local' in args: path=Path('todo.txt'); args.remove('--local')
    if path.is_dir(): path/= 'todo.txt'
    lines=path.read_text().splitlines() if path.exists() else []
    tasks=[parse(x) for x in lines]
    if cmd=='add' or unknown_as_add:
        subj=' '.join(x for x in args if not x.startswith('-'))
        if not subj.strip() or re.fullmatch(r'[+@]\S*',subj.strip()): print('Subject is empty'); return 1
        lines.append(subj.strip()); path.parent.mkdir(parents=True,exist_ok=True); path.write_text('\n'.join(lines)+'\n'); print('Added todo:'); print(' # D P Created    Finished   Due        Subject'); print('----------------------------------------------------------'); print(fmt(parse(lines[-1]),len(lines))); return 0
