from calendar import monthrange
from datetime import date, timedelta
import re


def _month_shift(day: date, amount: int) -> date:
    month0 = day.month - 1 + amount
    year, month = day.year + month0 // 12, month0 % 12 + 1
    return date(year, month, min(day.day, monthrange(year, month)[1]))


def _duration(text: str):
    strict = text.startswith("+")
    if strict:
        text = text[1:]
    match = re.fullmatch(r"(-?)(\d*)([dwmy]?)", text.lower())
    if not match:
        raise ValueError("invalid calendar range")
    sign, number, unit = match.groups()
    unit = unit or "d"
    number = int(number or 1) * (-1 if sign else 1)
    limits = {"d": 100, "w": 16, "m": 24, "y": 2}
    if abs(number) > limits[unit]:
        raise ValueError("calendar range is out of bounds")
    return strict, number, unit


def _shift(day, value, unit):
    if unit == "d":
        return day + timedelta(days=value)
    if unit == "w":
        return day + timedelta(days=value * 7)
    return _month_shift(day, value * (12 if unit == "y" else 1))


def calendar_range(spec: str, today: date | None = None) -> tuple[date, date]:
    """Return inclusive calendar start/end dates for a documented range."""
    today = today or date.today()
    if ".." in spec:
        left, right = spec.split("..", 1)
        _, a, au = _duration(left)
        _, b, bu = _duration(right)
        start, end = _shift(today, a, au), _shift(today, b, bu)
        return (start, end) if start <= end else (end, start)
    strict, count, unit = _duration(spec)
    if strict:
        if count >= 0:
            return today, _shift(today, count, unit) - timedelta(days=1)
