    if unit == "d":
        other = _shift(today, count, unit)
        return (today, other) if count >= 0 else (other, today)
    if unit == "w":
        # Calendar weeks are Sunday through Saturday in this view.
        start = today - timedelta(days=(today.weekday() + 1) % 7)
