        conf.parent.mkdir(parents=True,exist_ok=True)
        default=Path(__file__).with_name('ttdl.toml')
        conf.write_text(default.read_text() if default.exists() else '# TTDL configuration\n')
        print(f"Configuration initialized: '{conf}'")
